dificil.pergunta:
def pot(b, e):
    if e == 0:
        return 1
    return b * pot(b, e - 1)
Quanto vale pot(2, 5)?

def conta(n):
    if n == 0:
        print("Fim")
    else:
        print(n)
        conta(n - 1)
O que conta(3) mostra?

def f(n):
    if n == 0:
        return 0
    return 2 + f(n - 1)
Quanto vale f(4)?

def digitos(n):
    if n < 10:
        return 1
    return 1 + digitos(n // 10)
Quanto vale digitos(4527)?

def f(n):
    if n == 1:
        return 1
    return n + f(n - 2)
O que acontece com f(4)?

supremo.pergunta:
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
Quanto vale fib(6)?

def inverte(t):
    if t == "":
        return ""
    return inverte(t[1:]) + t[0]
Quanto vale inverte("sol")?

def soma_lista(l):
    if not l:
        return 0
    return l[0] + soma_lista(l[1:])
Quanto vale soma_lista([4, 7, 1])?

def m(a, b):
    if b == 0:
        return a
    return m(b, a % b)
Quanto vale m(48, 18)?
